{
  "implementation": "def solve(case):
    text = case['text']
    passes = case['passes']
    max_rounds = case['max_rounds']
    applications = []
    for _ in range(max_rounds):
        changed = False
        for p in passes:
            new_text = text.replace(p['old'], p['new'])
            if new_text != text:
                text = new_text
                applications.append(p['name'])
                changed = True
        if not changed:
            fixed_point = True
            break
    else:
        fixed_point = False
    return {'applications': applications, 'fixed_point': fixed_point, 'text': text}"
}
